function digitRoot(n) {
  while (n >= 10) {
    var sum = 0;
    while (n > 0) {
      sum += n % 10;
      n = Math.floor(n / 10);
    }
    n = sum;
  }
  return n;
}

console.log(digitRoot(9875));
